import os
import subprocess
import unittest


def run(*args):
    return subprocess.run(['sh', 'check.sh', *args], capture_output=True, text=True).returncode


class TestCheckExec(unittest.TestCase):
    def test_ok(self):
        open('a.txt', 'w').write('x')
        self.assertEqual(run('a.txt'), 0)

    def test_missing(self):
        self.assertEqual(run('nope.txt'), 1)

    def test_spaces(self):
        open('has space.txt', 'w').write('x')
        self.assertEqual(run('has space.txt'), 0)
        self.assertEqual(run('has space.txt', 'also missing.txt'), 1)


if __name__ == '__main__':
    unittest.main()
